package com.labex.labexagent.run;import static org.mockito.Mockito.*;import com.labex.entity.AgentSubagent;import com.labex.entity.StudentProject;import java.nio.file.Path;import java.util.concurrent.Executor;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class SubagentSchedulerTest {@TempDir Path root;@Test void runsSubagentWithIndependentContextAndSummarizes(){AgentSubagentService subs=mock(AgentSubagentService.class);AgentSubagentEventService events=mock(AgentSubagentEventService.class);SubagentResultSummaryService summaries=mock(SubagentResultSummaryService.class);Executor direct=Runnable::run;AgentSubagent a=new AgentSubagent();a.setSubagentId(1L);a.setIdentity("review");StudentProject p=new StudentProject();p.setWorkspacePath(root.toString());new SubagentScheduler(subs,events,summaries,direct).schedule("p",7,p,"c",9L,a,(ctx,agent)->"done").join();verify(subs).transition(a,SubagentState.RUNNING);verify(events).append(1L,"START","review");verify(summaries).complete(a,"done",true);}}
